792	export class WorksPageRuntime {
793	  private readonly root: ParentNode;
794	  private readonly projectsLoader: WorksProjectsLoader;
795	  private readonly backgroundCoordinator: WorksBackgroundCoordinator;
796	  private readonly authorRuntime = new WorksTheatreBridge();
797	  private readonly _interactionLock = new WorksInteractionLock();
798	
799	  private gridFeedRuntime: WorksGridFeedRuntime | null = null;
800	  private scene: WorksSceneManager | null = null;
801	  private uiRuntime: WorksPageUiRuntime | null = null;
802	  private introRuntime: WorksIntroPlaybackRuntime | null = null;
803	  private _wheelHintBound = false;
804	  private _authorCanvasHintBound = false;
805	  private _authorCanvasDragging = false;
806	  private _runRevision = 0;
807	  private _disposed = false;
808	  private readonly _scatterFilterCleanup: Array<() => void> = [];
809	  private elements: WorksPageElements = {
810	    root: null,
811	    canvas: null,
812	    grid: null,
813	    gridList: null,
814	    gridPagination: null,
815	    controls: null,
816	    toggle: null,
817	    filterWrap: null,
818	    filterButton: null,
819	    filterPanel: null,
820	    dragHint: null,
821	  };
822	  private state: WorksPageState = { ...WORK_PAGE_STATE_DEFAULT };
823	  private readonly _handleWheel = (event: WheelEvent): void => {
824	    if (this.state.view !== "scatter") return;
825	    if (this._authorCanvasDragging) return;
826	    if (Math.abs(event.deltaY) < 1) return;
827	    this.uiRuntime?.showDragHint();
828	  };
829	  private readonly _handleAuthorCanvasPointerDown = (): void => {
830	    this._authorCanvasDragging = true;
831	    this.uiRuntime?.hideDragHint();
832	  };
833	  private readonly _handleAuthorCanvasPointerUp = (): void => {
834	    this._authorCanvasDragging = false;
835	  };
836	  private readonly _handleAuthorCanvasPointerCancel = (): void => {
837	    this._authorCanvasDragging = false;
838	  };
839	
840	  constructor(root?: ParentNode | null) {
841	    this.root = root ?? document;
842	    this.projectsLoader = new WorksProjectsLoader();
843	    this.backgroundCoordinator = new WorksBackgroundCoordinator(this.root);
844	  }
845	
846	  async init(): Promise<void> {
847	    this._disposed = false;
848	    const runRevision = ++this._runRevision;
849	    const domRuntime = new WorksPageDomRuntime(this.root);
850	    this.elements = domRuntime.resolve();
851	    this.state = domRuntime.readState(this.elements);
852	    this.uiRuntime?.dispose();
853	    this.gridFeedRuntime?.dispose();
854	    this.gridFeedRuntime = null;
855	    this.uiRuntime = new WorksPageUiRuntime(this.elements);
856	    this.uiRuntime.applyInitialState(this.state);
857	    this.uiRuntime.syncViewLinks(this.state.category);
858	    this._unbindWheelHint();
859	    this._unbindAuthorCanvasHint();
860	    if (resolveWorksAuthorMode()) {
861	      this._hidePanel();
862	      this.state = { ...this.state, view: "scatter" };
863	      this.uiRuntime.hideGrid();
864	      this.uiRuntime.showCanvas();
865	      this.uiRuntime.hideViewToggle();
866	      this.uiRuntime.hideDragHint();
867	      this._bindWheelHint();
868	      this._bindAuthorCanvasHint();
869	      await this.authorRuntime.run(
870	        WORK_CANVAS_CONFIG.canvasId,
871	        this.elements.canvas,
872	      );
873	      if (!this._isActiveRun(runRevision)) return;
874	      this.uiRuntime.hideIntroIfReady();
875	      return;
876	    }
877	    await this.backgroundCoordinator.ensure();
878	    if (!this._isActiveRun(runRevision)) return;
879	    if (this.state.view === "grid") {
880	      this._showPanel();
881	      this._unbindWheelHint();
882	      this.scene?.dispose();
883	      this.scene = null;
884	      this.gridFeedRuntime = new WorksGridFeedRuntime(
885	        this.state,
886	        this.elements,
887	      );
888	      await this.gridFeedRuntime.init();
889	      if (!this._isActiveRun(runRevision)) return;
890	      this.gridFeedRuntime.bind();
891	      this.uiRuntime.hideCanvas();
892	      this.uiRuntime.enterGrid();
893	      return;
894	    }
895	    this._hidePanel();
896	    await this.startScatter(runRevision);
897	  }
898	
899	  dispose(): void {
900	    this._disposed = true;
901	    this._runRevision += 1;
902	    this._unbindScatterFilter();
903	    this._hidePanel();
904	    this._unbindWheelHint();
905	    this._unbindAuthorCanvasHint();
906	    this.projectsLoader.dispose();
907	    this.gridFeedRuntime?.dispose();
908	    this.gridFeedRuntime = null;
909	    this.scene?.dispose();
910	    this.scene = null;
911	    this.authorRuntime.dispose();
912	    this.introRuntime?.dispose();
913	    this.introRuntime = null;
914	    this.backgroundCoordinator.dispose();
915	    this._interactionLock.dispose();
916	    this.uiRuntime?.dispose();
917	    this.uiRuntime = null;
918	    this.elements = {
919	      root: null,
920	      canvas: null,
921	      grid: null,
922	      gridList: null,
923	      gridPagination: null,
924	      controls: null,
925	      toggle: null,
926	      filterWrap: null,
927	      filterButton: null,
928	      filterPanel: null,
929	      dragHint: null,
930	    };
