933	  private async startScatter(runRevision: number): Promise<void> {
934	    const hasWebgl = EnvSetup.checkWebGL();
935	    const hasCanvasHost = EnvSetup.checkCanvas(
936	      WORK_CANVAS_CONFIG.canvasId,
937	      this.root,
938	    );
939	    const canRun = hasWebgl && hasCanvasHost;
940	    if (!canRun) {
941	      this._fallbackToGridView();
942	      return;
943	    }
944	
945	    const projectsPromise = this.projectsLoader.load(this.state);
946	    const introStatePromise = this._playScatterIntro(runRevision);
947	    let projects: WorkProjectItem[];
948	    try {
949	      projects = await projectsPromise;
950	    } catch (error) {
951	      if (!this._isActiveRun(runRevision)) return;
952	      if (this.projectsLoader.isAbortedError(error)) return;
953	      throw error;
954	    }
955	    if (!this._isActiveRun(runRevision)) return;
956	    const introState = await introStatePromise;
957	    if (!this._isActiveRun(runRevision)) return;
958	
959	    if (projects.length === 0) {
960	      this._fallbackToGridView();
961	      return;
962	    }
963	
964	    this.scene?.dispose();
965	    this.scene = new WorksSceneManager({
966	      root: this.root,
967	      config: WORK_CANVAS_CONFIG,
968	      layout: WORK_LAYOUT,
969	      projects,
970	      introEntryState: introState
971	        ? {
972	            camera: introState.camera,
973	            cameraTarget: introState.cameraTarget,
974	          }
975	        : null,
976	      initialCategory: this.state.category,
977	      onSelect: (detailPath) => this.navigateToDetail(detailPath),
978	      onInteractionStart: () => this.uiRuntime?.hideDragHint(),
979	      canvasId: WORK_CANVAS_CONFIG.canvasId,
980	      pixelRatioMax: WORK_PIXEL_RATIO_MAX,
981	      renderer: WORK_RENDERER_CONFIG,
982	      placeholderImage: WORK_PLACEHOLDER_IMAGE,
983	    });
984	    this.scene.init();
985	    this.scene.setViewMode("scatter");
986	    this.scene.showCanvas();
987	    this._hidePanel();
988	    this.scene.applyInitialScatterState();
989	    if (!this._isActiveRun(runRevision)) return;
990	
991	    this.uiRuntime?.syncFilterSelection(this.state.category);
992	    this._bindScatterFilter(this.scene);
993	
994	    this.uiRuntime?.hideIntroIfReady();
995	    this.uiRuntime?.hideGrid();
996	    this._bindWheelHint();
997	    this.uiRuntime?.showViewToggle();
998	    if (WORK_HINT_CONFIG.enabled) {
999	      this.uiRuntime?.showDragHintIfNeeded(this.state);
1000	    }
1001	  }
1002	
1003	  private async _playScatterIntro(
1004	    runRevision: number,
1005	  ): Promise<SceneFromState | null> {
1006	    if (!WORK_INTRO_CONFIG.enabled) return null;
1007	    if (this.state.view !== "scatter") return null;
1008	    if (!(this.elements.canvas instanceof HTMLCanvasElement)) return null;
1009	
1010	    this._interactionLock.lock();
1011	    this.introRuntime?.dispose();
1012	    const introRuntime = new WorksIntroPlaybackRuntime();
1013	    this.introRuntime = introRuntime;
1014	
1015	    try {
1016	      const introState = await introRuntime.run(
1017	        WORK_CANVAS_CONFIG.canvasId,
1018	        this.elements.canvas,
1019	      );
1020	      if (!this._isActiveRun(runRevision)) return null;
1021	      return introState;
1022	    } catch (error) {
1023	      console.warn(
1024	        "[WorksPageRuntime._playScatterIntro] Intro playback failed.",
1025	        error,
1026	      );
1027	      return null;
1028	    } finally {
1029	      if (this.introRuntime === introRuntime) {
1030	        introRuntime.dispose();
1031	        this.introRuntime = null;
1032	      }
1033	      this._interactionLock.unlock();
1034	    }
1035	  }
1036	
1037	  private _isActiveRun(runRevision: number): boolean {
1038	    return !this._disposed && this._runRevision === runRevision;
1039	  }
1040	
1041	  private _bindWheelHint(): void {
1042	    if (this._wheelHintBound) return;
1043	    window.addEventListener("wheel", this._handleWheel, { passive: true });
1044	    this._wheelHintBound = true;
1045	  }
1046	
1047	  private _unbindWheelHint(): void {
1048	    if (!this._wheelHintBound) return;
1049	    window.removeEventListener("wheel", this._handleWheel);
1050	    this._wheelHintBound = false;
1051	  }
1052	
1053	  private _bindAuthorCanvasHint(): void {
1054	    if (this._authorCanvasHintBound) return;
1055	    const canvas = this.elements.canvas;
1056	    if (!(canvas instanceof HTMLCanvasElement)) return;
1057	    canvas.addEventListener("pointerdown", this._handleAuthorCanvasPointerDown);
1058	    window.addEventListener("pointerup", this._handleAuthorCanvasPointerUp);
1059	    window.addEventListener(
1060	      "pointercancel",
1061	      this._handleAuthorCanvasPointerCancel,
1062	    );
1063	    this._authorCanvasHintBound = true;
1064	  }
1065	
1066	  private _unbindAuthorCanvasHint(): void {
1067	    if (!this._authorCanvasHintBound) return;
1068	    const canvas = this.elements.canvas;
1069	    if (canvas instanceof HTMLCanvasElement) {
1070	      canvas.removeEventListener(
1071	        "pointerdown",
1072	        this._handleAuthorCanvasPointerDown,
1073	      );
1074	    }
1075	    window.removeEventListener("pointerup", this._handleAuthorCanvasPointerUp);
1076	    window.removeEventListener(
1077	      "pointercancel",
1078	      this._handleAuthorCanvasPointerCancel,
1079	    );
1080	    this._authorCanvasHintBound = false;
1081	    this._authorCanvasDragging = false;
1082	  }
1083	
1084	  private _showPanel(): void {
1085	    this._setPanelVisible(true);
1086	  }
1087	
1088	  private _hidePanel(): void {
1089	    this._setPanelVisible(false);
1090	  }
1091	
1092	  private _setPanelVisible(visible: boolean): void {
1093	    const panel = Panel.getInstance();
1094	    panel.init();
1095	    if (visible) {
1096	      panel.setVisibleOn();
1097	      return;
1098	    }
1099	    panel.setVisibleOff();
1100	  }
