1102	  private navigateToDetail(detailPath: string): void {
1103	    const base = document.documentElement?.getAttribute?.("data-base") ?? "";
1104	    const detailUrl = new URL(detailPath, window.location.origin);
1105	    detailUrl.searchParams.set("view", this.state.view);
1106	    if (this.state.category) {
1107	      detailUrl.searchParams.set("category", this.state.category);
1108	    } else {
1109	      detailUrl.searchParams.delete("category");
1110	    }
1111	    if (this.state.page > 1) {
1112	      detailUrl.searchParams.set("page", String(this.state.page));
1113	    } else {
1114	      detailUrl.searchParams.delete("page");
1115	    }
1116	    const href =
1117	      `${base}${detailUrl.pathname}${detailUrl.search}${detailUrl.hash}`.replace(
1118	        /\/+/g,
1119	        "/",
1120	      );
1121	    window.location.assign(href);
1122	  }
1123	
1124	  private _fallbackToGridView(): void {
1125	    this._showPanel();
1126	    this.uiRuntime?.hideIntroIfReady();
1127	    this.uiRuntime?.hideCanvas();
1128	    this.uiRuntime?.showGrid();
1129	    this.uiRuntime?.showViewToggle();
1130	  }
1131	
1132	  private _unbindScatterFilter(): void {
1133	    this._scatterFilterCleanup.forEach((fn) => fn());
1134	    this._scatterFilterCleanup.length = 0;
1135	  }
1136	
1137	  private _bindScatterFilter(scene: WorksSceneManager): void {
1138	    this._unbindScatterFilter();
1139	    const wrap = this.elements.filterWrap;
1140	    const filterButton = this.elements.filterButton;
1141	    const filterPanel = this.elements.filterPanel;
1142	    if (!wrap || !filterButton || !filterPanel) return;
1143	
1144	    let closeAriaTimer: number | null = null;
1145	    const clearCloseAriaTimer = (): void => {
1146	      if (closeAriaTimer === null) return;
1147	      window.clearTimeout(closeAriaTimer);
1148	      closeAriaTimer = null;
1149	    };
1150	
1151	    const closePanel = (): void => {
1152	      clearCloseAriaTimer();
1153	      filterButton.setAttribute("aria-expanded", "false");
1154	      filterPanel.classList.remove("is-open");
1155	      // 패널 닫힘 트랜지션 후: 포커스 정리 + aria-hidden (WORKS_FILTER_TRANSITION_MS와 동기)
1156	      closeAriaTimer = window.setTimeout(() => {
1157	        closeAriaTimer = null;
1158	        const ae = document.activeElement;
1159	        if (ae instanceof Node && filterPanel.contains(ae)) {
1160	          filterButton.focus({ preventScroll: true });
1161	        }
1162	        filterPanel.setAttribute("aria-hidden", "true");
1163	      }, WORKS_FILTER_TRANSITION_MS);
1164	    };
1165	
1166	    const openPanel = (): void => {
1167	      clearCloseAriaTimer();
1168	      filterPanel.setAttribute("aria-hidden", "false");
1169	      filterPanel.classList.add("is-open");
1170	      filterButton.setAttribute("aria-expanded", "true");
1171	    };
1172	
1173	    const togglePanel = (): void => {
1174	      if (filterPanel.classList.contains("is-open")) {
1175	        closePanel();
1176	      } else {
1177	        openPanel();
1178	      }
1179	    };
1180	
1181	    const onFilterButtonClick = (event: MouseEvent): void => {
1182	      event.stopPropagation();
1183	      togglePanel();
1184	    };
1185	    filterButton.addEventListener("click", onFilterButtonClick);
1186	    this._scatterFilterCleanup.push(() =>
1187	      filterButton.removeEventListener("click", onFilterButtonClick),
1188	    );
1189	
1190	    const onPanelClick = (event: MouseEvent): void => {
1191	      const target = event.target as HTMLElement | null;
1192	      const option = target?.closest<HTMLElement>("[data-works-filter-option]");
1193	      if (!option) return;
1194	      const raw = option.dataset.category?.trim() ?? "";
1195	      const category = raw === "" ? null : raw;
1196	      this.state = { ...this.state, category };
1197	      this.elements.root?.setAttribute(
1198	        "data-category",
1199	        category === null ? "" : category,
1200	      );
1201	      scene.applyCategory(category);
1202	      this.uiRuntime?.syncFilterSelection(category, { animateLabel: true });
1203	      this.uiRuntime?.syncViewLinks(category);
1204	      this._syncScatterUrl(category);
1205	      closePanel();
1206	    };
1207	    filterPanel.addEventListener("click", onPanelClick);
1208	    this._scatterFilterCleanup.push(() =>
1209	      filterPanel.removeEventListener("click", onPanelClick),
1210	    );
1211	
1212	    const onDocumentClick = (event: MouseEvent): void => {
1213	      if (!wrap.contains(event.target as Node)) {
1214	        closePanel();
1215	      }
1216	    };
1217	    document.addEventListener("click", onDocumentClick);
1218	    this._scatterFilterCleanup.push(() =>
1219	      document.removeEventListener("click", onDocumentClick),
1220	    );
1221	
1222	    const onKeyDown = (event: KeyboardEvent): void => {
1223	      if (event.key !== "Escape") return;
1224	      closePanel();
1225	    };
1226	    document.addEventListener("keydown", onKeyDown);
1227	    this._scatterFilterCleanup.push(() =>
1228	      document.removeEventListener("keydown", onKeyDown),
1229	    );
1230	
1231	    this._scatterFilterCleanup.push(() => {
1232	      clearCloseAriaTimer();
1233	      if (!filterPanel.classList.contains("is-open")) {
1234	        filterPanel.setAttribute("aria-hidden", "true");
1235	      }
1236	    });
1237	  }
1238	
1239	  private _syncScatterUrl(category: string | null): void {
1240	    const url = new URL(window.location.href);
1241	    url.searchParams.set("view", "scatter");
1242	    if (category) {
1243	      url.searchParams.set("category", category);
1244	    } else {
1245	      url.searchParams.delete("category");
1246	    }
1247	    if (this.state.page > 1) {
1248	      url.searchParams.set("page", String(this.state.page));
1249	    } else {
1250	      url.searchParams.delete("page");
1251	    }
1252	    window.history.replaceState({}, "", url);
1253	  }
1254	}
