import { UI_PANEL, UI_PANEL_AUTOPLAY } from "../config/component.config.js";
import type { ComponentConfig } from "../types/dom.types.js";
import { Helpers } from "../utils/Helpers.js";
import { UI } from "./UI.js";

export class Panel extends UI {
  private _progressRoot: HTMLElement | null = null;
  private _progressSegments: HTMLElement[] = [];
  private _rulerTicks: HTMLElement[] = [];
  private _progressTimerId: number | null = null;
  private _rulerFrameId: number | null = null;
  private _rulerStartedAt = 0;
  private _progressStep = 0;

  static getInstance(options: Partial<ComponentConfig> = {}): Panel {
    const selector = options.selector ?? UI_PANEL.selector;
    return UI.getOrCreate(Panel, { ...options, selector }) as Panel;
  }

  constructor(config: ComponentConfig = { selector: UI_PANEL.selector }) {
    const selector = config.selector ?? UI_PANEL.selector;
    super({ ...config, selector });
  }

  protected override mount(): void {
    if (!this.element) return;
    this._collectElements();
    this.element.classList.toggle(UI_PANEL.visibleClass, this._visible);
    this._syncAutoplay(this._visible);
  }

  protected override applyVisibility(visible: boolean): void {
    this.element?.classList.toggle(UI_PANEL.visibleClass, visible);
    this._syncAutoplay(visible);
  }

  override dispose(): void {
    this._stopAutoplay();
    this._progressRoot = null;
    this._progressSegments = [];
    this._rulerTicks = [];
    super.dispose();
  }

  private _collectElements(): void {
    if (!this.element) return;
    this._progressRoot = this.element.querySelector<HTMLElement>(
      UI_PANEL_AUTOPLAY.progressSelector,
    );
    this._progressSegments = Array.from(
      this.element.querySelectorAll<HTMLElement>(
        UI_PANEL_AUTOPLAY.progressSegmentSelector,
      ),
    );
    this._rulerTicks = Array.from(
      this.element.querySelectorAll<HTMLElement>(
        UI_PANEL_AUTOPLAY.rulerTickSelector,
      ),
    ).sort((left, right) => {
      const leftValue = Number(left.dataset.value ?? 0);
      const rightValue = Number(right.dataset.value ?? 0);
      return leftValue - rightValue;
    });
    this._progressStep = 0;
    this._applyProgressFrame(0);
    this._applyRulerFrame(0);
  }

  private _syncAutoplay(visible: boolean): void {
    if (!visible) {
      this._stopAutoplay();
      return;
    }
    this._startAutoplay();
  }

  private _startAutoplay(): void {
    if (this._progressSegments.length > 0 && this._progressTimerId == null) {
      this._applyProgressFrame(this._progressStep);
      this._progressTimerId = window.setInterval(() => {
        this._progressStep =
          (this._progressStep + 1) % (this._progressSegments.length + 1);
        this._applyProgressFrame(this._progressStep);
      }, UI_PANEL_AUTOPLAY.progressIntervalMs);
    }

    if (this._rulerTicks.length === 0 || this._rulerFrameId != null) return;
    this._rulerStartedAt = performance.now();
    this._tickRuler();
  }

  private _stopAutoplay(): void {
    if (this._progressTimerId != null) {
      window.clearInterval(this._progressTimerId);
      this._progressTimerId = null;
    }
    if (this._rulerFrameId != null) {
      window.cancelAnimationFrame(this._rulerFrameId);
      this._rulerFrameId = null;
    }
  }

  private _applyProgressFrame(activeCount: number): void {
    if (this._progressRoot) {
      this._progressRoot.setAttribute(
        "aria-valuenow",
        String(Math.min(activeCount, this._progressSegments.length)),
      );
    }

    this._progressSegments.forEach((segment, index) => {
      segment.classList.toggle("is-filled", index < activeCount);
    });
  }

  private _tickRuler(): void {
    const tickCount = this._rulerTicks.length;
    if (tickCount === 0) {
      this._rulerFrameId = null;
      return;
    }
    const duration = Math.max(UI_PANEL_AUTOPLAY.rulerDurationMs, 1);
    const elapsed = (performance.now() - this._rulerStartedAt) % duration;
    const progress = elapsed / duration;
    this._applyRulerFrame(progress * tickCount);
    this._rulerFrameId = window.requestAnimationFrame(() => {
      this._tickRuler();
    });
  }

  private _applyRulerFrame(activeProgress: number): void {
    this._rulerTicks.forEach((tick, index) => {
      const strength = Helpers.clamp01(activeProgress - index);
      tick.style.setProperty("--ruler-strength", strength.toFixed(4));
      tick.classList.toggle(UI_PANEL_AUTOPLAY.activeClass, strength >= 0.98);
    });
  }
}

