&__gallery {
  padding-right: var(--gutter-lg);
  &-list {
    position: relative;
  }
  &-item {
    width: 48%;
    display: flex;
    flex-direction: column;
    &:nth-child(even) {
      margin-left: auto;
      margin-top: -24rem;
    }
    &:nth-child(odd) {
      margin-right: auto;
    }
    & > .no-works-canvas__grid-link {
      margin-top: var(--gutter-sm);
      align-self: flex-start;
    }
    &__img {
      margin: 0;
      @include img-auto-cover(62.5%);

      img,
      video {
        @include img-cover;
        transition: transform var(--transition-default);
      }
    }

    &__img-wrap {
      position: relative;
      padding: var(--gutter-xs);
      border: 1px solid var(--clr-border-default);
    }

    &__corner {
      color: color-mix(in srgb, var(--clr-white-100) 72%, transparent);
    }

    &__img-inner {
      overflow: hidden;
    }

    &__link {
      display: block;
      color: inherit;
      text-decoration: none;

      &:hover {
        #{$root}__gallery-item__img-inner img,
        #{$root}__gallery-item__img-inner video {
          transform: scale(1.08);
        }
      }
    }

    &__body {
      margin-top: var(--gutter-sm);
      display: flex;
      justify-content: space-between;
    }
    &__title {
      @include font("f-heading-3");
      font-weight: 700;
    }
    &__info {
      display: flex;
      margin-top: var(--gutter-sm);
      gap: var(--gutter-xs);
    }
  }
}
&__inner {
  display: grid;
  grid-template-columns: 3fr 9fr;
  gap: var(--gutter-md);
}
&__filter {
  position: sticky;
  left: 0;
  top: calc(var(--header-height) + var(--gutter-2xl));
  height: fit-content;
