import type * as THREE from "three";
import type { SceneFromState } from "./core.types.js";
import type { SceneLightsStateSnapshot } from "./object.types.js";

export interface WorkApiItem {
  no: string;
  title: string;
  thumbnailImage: string;
  thumbnailVideo: string | null;
  category: string;
  categoryLabel: string;
  tagLabels: string[];
  detailPath: string;
  modalPath: string;
  client: string | null;
  updatedAtLabel: string | null;
}

export interface WorkProjectVisualPreset {
  bg: string;
  ac: string;
  w: number;
  h: number;
}

export interface WorkProjectItem extends WorkApiItem, WorkProjectVisualPreset {}

export interface WorksListResponse {
  items: WorkApiItem[];
  nextOffset: number | null;
  hasMore: boolean;
}


export interface WorkCanvasConfig {
  canvasId: string;
  spreadX: number;
  spreadY: number;
  totalCards: number;
  camZ: number;
  cardWidth: number;
  cardHeight: number;
  camFov: number;
  camNear: number;
  camFar: number;
}

export interface WorkLayoutConstants {
  camLerp: number;
  camZLerp: number;
  velDecay: number;
  opacityLerp: number;
  scaleLerp: number;
  positionLerp: number;
}

export interface WorksIntroConfig {
  enabled: boolean;
  hideWhenReady: boolean;
  toggleRevealDelayMs: number;

